import{_ as o,a0 as a,w as s,s as r,ao as l,I as i,x as u,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"每日Ubuntu小技巧——在Ubuntu中使用音乐软件“声破天”Spotify | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧——在Ubuntu中使用音乐软件“声破天”Spotify | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧——在Ubuntu中使用音乐软件“声破天”Spotify | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧——在Ubuntu中使用音乐软件“声破天”Spotify | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/Daily Ubuntu Tips – Use Spotify In Ubuntu Linux","title":"每日Ubuntu小技巧——在Ubuntu中使用音乐软件“声破天”Spotify","tag":"201402","desc":""},"relativePath":"201402/Daily Ubuntu Tips – Use Spotify In Ubuntu Linux.md","filePath":"[post].md"}'),b={name:"201402/Daily Ubuntu Tips – Use Spotify In Ubuntu Linux.md"};function d(f,t,y,U,m,T){const n=a("Link");return s(),r("div",null,[t[11]||(t[11]=l(`<h1 id="每日ubuntu小技巧——在ubuntu中使用音乐软件-声破天-spotify" tabindex="-1">每日Ubuntu小技巧——在Ubuntu中使用音乐软件“声破天”Spotify <a class="header-anchor" href="#每日ubuntu小技巧——在ubuntu中使用音乐软件-声破天-spotify" aria-label="Permalink to “每日Ubuntu小技巧——在Ubuntu中使用音乐软件“声破天”Spotify”">​</a></h1><p>Spotify（译者注：下面译为&quot;声破天&quot;）云音乐服务已经解除了对所有用户及平台（web端/桌面端/手机端）的时间限制，现在用户可以在任何平台、任何时间无限制地听免费音乐。</p><p>起初，声破天有个时间限制，新用户自注册帐号时起的前六个月可以免费听音乐，但是这个限制取决于你所在的地区，不过现在所有免费帐号都可以无限制听音乐。</p><p>任何使用 Ubuntu 桌面客户端听音乐的用户也没有了之前对免费账户听音乐的限制，Ubuntu 用户可以使用他们最喜欢的桌面操作系统来享受免费音乐。</p><p>如果你现在有点小激动，但是还没有安装声破天，那么这里有一个快捷方法来指导你如何在 Ubuntu 上安装最新版本的声破天。</p><p>一些地区还不支持声破天的注册，这些地区的用户必须得想点别的办法了（译者注：需要使用代理），这是因为声破天并不是所有国家都支持。下面图片显示的是目前声破天支持的国家列表：</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/01/spotifycountrylist.jpg" alt=""></p><h3 id="在-ubuntu-安装上声破天" tabindex="-1">在 Ubuntu 安装上声破天 <a class="header-anchor" href="#在-ubuntu-安装上声破天" aria-label="Permalink to “在 Ubuntu 安装上声破天”">​</a></h3><p>要想在 Ubuntu 上安装声破天，需要打开终端然后输入下面命令，将声破天的软件仓库添加到 Ubuntu</p><pre><code>sudo apt-add-repository -y &quot;deb http://repository.spotify.com stable non-free&quot;
</code></pre><p>下一步，将声破天的仓库密钥添加到 Ubuntu，运行下面命令：</p><pre><code>sudo apt-key adv --keyserver keyserver.ubuntu.com --recv-keys 94558F59
</code></pre><p>最后，更新系统的软件包仓库并且安装声破天，运行下面命令：</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get install spotify-client
</code></pre><p>就这么简单！</p><p>在安装完声破天后，你需要打开 Ubuntu 的面板，在里面找到这个软件。打开后，尽情享受你的免费音乐吧！</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/01/spotifyclientubuntu.png" alt=""></p><hr>`,18)),i("p",null,[t[1]||(t[1]=u("via: ",-1)),e(n,{href:"http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-use-spotify-in-ubuntu-linux/"},{default:p(()=>[...t[0]||(t[0]=[u("http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-use-spotify-in-ubuntu-linux/",-1)])]),_:1})]),i("p",null,[t[4]||(t[4]=u("译者：",-1)),e(n,{href:"https://github.com/liuaiping"},{default:p(()=>[...t[2]||(t[2]=[u("liuaiping",-1)])]),_:1}),t[5]||(t[5]=u(" 校对：",-1)),e(n,{href:"https://github.com/carolinewuyan"},{default:p(()=>[...t[3]||(t[3]=[u("Caroline",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=u("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[u("LCTT",-1)])]),_:1}),t[9]||(t[9]=u(" 原创翻译，",-1)),e(n,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[u("Linux中国",-1)])]),_:1}),t[10]||(t[10]=u(" 荣誉推出",-1))])])}const C=o(b,[["render",d]]);export{w as __pageData,C as default};
